create function pg_temp.d_deny(q text,c text)returns void language plpgsql as $$declare actual text;begin begin execute q;exception when others then actual:=sqlstate;end;if actual is distinct from c then raise exception 'deadline expected %, got %',c,actual;end if;end$$;
